// nv_scim_shim.c — what the NucleoOS build of sc-im adds: the help text compiled in (the
// package folder is not visible to a terminal program), read through a memory stream.
#include <stdio.h>
#include "scim_help.h"   // generated by build_wsl.sh: unsigned char doc[]; unsigned int doc_len;

FILE *nv_scim_help_open(void) {
    return fmemopen(doc, doc_len, "r");
}
